#include "imgdataaug.h"
int main(int argc,char**argv){cv::setNumThreads(1);cv::Mat input(64,64,CV_8UC3),mask(64,64,CV_8UC1);for(int y=0;y<64;y++)for(int x=0;x<64;x++){input.at<cv::Vec3b>(y,x)={uchar(x*3),uchar(y*3),uchar((x+y)*2)};mask.at<uchar>(y,x)=((x+y)%11==0)?255:((x/8+y/8)%4);}std::string dir=argv[1];cv::imwrite(dir+"/input.png",input);cv::imwrite(dir+"/mask.png",mask);for(unsigned seed:{11,42,23124534}){dd::NoiseParams n(false);n._prob=.4;dd::DistortParams d(false);d._prob=.4;dd::GeometryParams g(.3,true,true,false,false,true,true,"constant");dd::ImgRandAugCV a(true,true,dd::CropParams(48),dd::CutoutParams(.3),g,n,d);a.seed_rnd_gen(seed);cv::setRNGSeed(seed);cv::Mat im=input.clone(),m=mask.clone();a.augment_with_segmap(im,m);cv::imwrite(dir+"/"+std::to_string(seed)+"-image.png",im);cv::imwrite(dir+"/"+std::to_string(seed)+"-mask.png",m);}}
